// http.serve on wasm-server (`--target wasm-server`): the host creates an
// instance for each request and calls the component's wasi:http handler.
// That runs the program's `main`, as a native program would; when `main`
// calls http.serve, the router answers this one request and serve returns.
// So the same program runs as a server of its own and on the platform.
//
// The bindings (wasm/guest.h) are generated by wit-bindgen from
// compiler/wasm/wit; see compiler/wasm/README.md.

#include "guest.h"

static lt_err lt_program_main(void);
static void lt_http_dispatch(lt_fn handler, const lt_http_raw *req, lt_http_out *out);

// the request this instance is answering
static struct {
    wasi_http_types_borrow_incoming_request_t req;
    wasi_http_types_own_response_outparam_t out;
    bool active; // the handler is running
    bool answered;
    int64_t max_body;
} lt_wasm_http;

static void lt_wasm_log_error(const char *msg) {
    lt_text *m = lt_text_cstr(msg);
    lt_log("ERROR", m);
    lt_text_drop(m);
}

static void lt_wasm_respond(int64_t status, lt_texts *headers, const uint8_t *body, size_t len) {
    if (lt_wasm_http.answered) return;
    lt_wasm_http.answered = true;
    wasi_http_types_own_fields_t fields = wasi_http_types_constructor_fields();
    wasi_http_types_borrow_fields_t bf = wasi_http_types_borrow_fields(fields);
    bool has_type = false;
    bool bodiless = status < 200 || status == 204 || status == 304;
    for (int64_t i = 0; headers && i + 1 < headers->len; i += 2) {
        lt_text *hn = headers->items[i], *hv = headers->items[i + 1];
        if (lt_ieq(hn->data, hn->len, "content-type")) has_type = true;
        // the host frames the body itself
        if (lt_ieq(hn->data, hn->len, "content-length") || lt_ieq(hn->data, hn->len, "connection") || lt_ieq(hn->data, hn->len, "transfer-encoding")) continue;
        // a value with line breaks is several headers (Set-Cookie)
        const char *v = hv->data, *end = hv->data + hv->len;
        while (v <= end) {
            const char *nl = memchr(v, '\n', (size_t)(end - v));
            const char *stop = nl ? nl : end;
            wasi_http_types_field_name_t name = { (uint8_t *)hn->data, (size_t)hn->len };
            wasi_http_types_field_value_t value = { (uint8_t *)v, (size_t)(stop - v) };
            wasi_http_types_header_error_t err;
            wasi_http_types_method_fields_append(bf, &name, &value, &err);
            if (!nl) break;
            v = nl + 1;
        }
    }
    if (!has_type && len > 0 && !bodiless) {
        wasi_http_types_field_name_t name = { (uint8_t *)"content-type", 12 };
        wasi_http_types_field_value_t value = { (uint8_t *)"text/plain; charset=utf-8", 25 };
        wasi_http_types_header_error_t err;
        wasi_http_types_method_fields_append(bf, &name, &value, &err);
    }
    wasi_http_types_own_outgoing_response_t resp = wasi_http_types_constructor_outgoing_response(fields);
    wasi_http_types_borrow_outgoing_response_t br = wasi_http_types_borrow_outgoing_response(resp);
    wasi_http_types_method_outgoing_response_set_status_code(br, (uint16_t)status);
    wasi_http_types_own_outgoing_body_t ob;
    wasi_http_types_method_outgoing_response_body(br, &ob);
    wasi_http_types_result_own_outgoing_response_error_code_t result = { .is_err = false, .val.ok = resp };
    wasi_http_types_static_response_outparam_set(lt_wasm_http.out, &result);
    if (len > 0 && !bodiless) {
        wasi_http_types_own_output_stream_t stream;
        wasi_http_types_method_outgoing_body_write(wasi_http_types_borrow_outgoing_body(ob), &stream);
        // blocking-write-and-flush takes at most 4096 bytes at a time
        for (size_t off = 0; off < len; off += 4096) {
            size_t n = len - off < 4096 ? len - off : 4096;
            guest_list_u8_t chunk = { (uint8_t *)body + off, n };
            wasi_io_streams_stream_error_t err;
            if (!wasi_io_streams_method_output_stream_blocking_write_and_flush(wasi_io_streams_borrow_output_stream(stream), &chunk, &err)) break;
        }
        wasi_io_streams_output_stream_drop_own(stream);
    }
    wasi_http_types_error_code_t finish_err;
    wasi_http_types_static_outgoing_body_finish(ob, NULL, &finish_err);
}

static void lt_wasm_respond_text(int64_t status, const char *msg) {
    lt_wasm_respond(status, NULL, (const uint8_t *)msg, strlen(msg));
}

// The request's body, up to max_body bytes; false when it is larger.
static bool lt_wasm_read_body(lt_buf *b, int64_t max_body) {
    wasi_http_types_own_incoming_body_t body;
    if (!wasi_http_types_method_incoming_request_consume(lt_wasm_http.req, &body)) return true;
    wasi_http_types_own_input_stream_t stream;
    if (!wasi_http_types_method_incoming_body_stream(wasi_http_types_borrow_incoming_body(body), &stream)) return true;
    bool ok = true;
    for (;;) {
        guest_list_u8_t chunk;
        wasi_io_streams_stream_error_t err;
        if (!wasi_io_streams_method_input_stream_blocking_read(wasi_io_streams_borrow_input_stream(stream), 65536, &chunk, &err)) break; // the end, or failed
        if (b->len + (int64_t)chunk.len > max_body) ok = false;
        else lt_buf_put(b, (const char *)chunk.ptr, (int64_t)chunk.len);
        guest_list_u8_free(&chunk);
        if (!ok) break;
    }
    wasi_io_streams_input_stream_drop_own(stream);
    wasi_http_types_future_trailers_drop_own(wasi_http_types_static_incoming_body_finish(body));
    return ok;
}

static const char *lt_wasm_method_name(wasi_http_types_method_t *m, int64_t *len) {
    static const char *names[] = { "GET", "HEAD", "POST", "PUT", "DELETE", "CONNECT", "OPTIONS", "TRACE", "PATCH" };
    if (m->tag == WASI_HTTP_TYPES_METHOD_OTHER) {
        *len = (int64_t)m->val.other.len;
        return (const char *)m->val.other.ptr;
    }
    *len = (int64_t)strlen(names[m->tag]);
    return names[m->tag];
}

static lt_err lt_http_serve_on(lt_text *host, int64_t port, int64_t max_body, int64_t idle_ns, int64_t read_ns, int64_t write_ns, lt_fn handler) {
    (void)host; (void)port; (void)idle_ns; (void)read_ns; (void)write_ns;
    if (!lt_wasm_http.active) return lt_make_failure(lt_text_cstr("http.serve: there is no request to answer (this program was built for wasm-server)"));
    if (lt_wasm_http.answered) return lt_make_failure(lt_text_cstr("http.serve: called twice; the request is already answered"));
    wasi_http_types_borrow_incoming_request_t req = lt_wasm_http.req;
    lt_http_raw r;
    memset(&r, 0, sizeof r);
    wasi_http_types_method_t method;
    wasi_http_types_method_incoming_request_method(req, &method);
    r.method = lt_wasm_method_name(&method, &r.method_len);
    guest_string_t pq = { 0 };
    wasi_http_types_method_incoming_request_path_with_query(req, &pq);
    const char *p = pq.ptr ? (const char *)pq.ptr : "/";
    int64_t plen = pq.ptr ? (int64_t)pq.len : 1;
    const char *q = memchr(p, '?', (size_t)plen);
    r.path = p;
    r.path_len = q ? q - p : plen;
    r.query = q ? q + 1 : NULL;
    r.query_len = q ? plen - (q + 1 - p) : 0;
    wasi_http_types_own_headers_t hs = wasi_http_types_method_incoming_request_headers(req);
    wasi_http_types_list_tuple2_field_name_field_value_t entries;
    wasi_http_types_method_fields_entries(wasi_http_types_borrow_fields(hs), &entries);
    for (size_t i = 0; i < entries.len && r.nheaders < 64; i++) {
        r.hname[r.nheaders] = (const char *)entries.ptr[i].f0.ptr;
        r.hname_len[r.nheaders] = (int64_t)entries.ptr[i].f0.len;
        r.hvalue[r.nheaders] = (const char *)entries.ptr[i].f1.ptr;
        r.hvalue_len[r.nheaders] = (int64_t)entries.ptr[i].f1.len;
        r.nheaders++;
    }
    // the host passes the client's address in x-forwarded-for
    char ip[64] = "";
    for (int64_t i = 0; i < r.nheaders; i++)
        if (lt_ieq(r.hname[i], r.hname_len[i], "x-forwarded-for")) {
            int64_t n = 0;
            while (n < r.hvalue_len[i] && n < 63 && r.hvalue[i][n] != ',') n++;
            memcpy(ip, r.hvalue[i], (size_t)n);
            ip[n] = 0;
        }
    r.client_ip = ip;
    lt_buf body = { 0 };
    lt_err e = { 0 };
    if (!lt_wasm_read_body(&body, max_body > 0 ? max_body : ((int64_t)10 << 20))) {
        lt_wasm_respond_text(413, "request body too large");
    } else {
        r.body = body.d ? body.d : "";
        r.body_len = body.len;
        lt_http_out out;
        memset(&out, 0, sizeof out);
        lt_http_dispatch(handler, &r, &out);
        bool file = out.file && out.file->len > 0;
        if (out.writer.fn || file) {
            lt_wasm_log_error(file ? "http.file isn't available on wasm-server (serve static files with the app's `static` directory)" : "http.stream isn't available on wasm-server");
            lt_wasm_respond_text(500, "internal server error");
        } else {
            lt_wasm_respond(out.status, out.headers, out.body ? out.body->data : NULL, out.body ? (size_t)out.body->len : 0);
        }
        if (out.headers) {
            for (int64_t i = 0; i < out.headers->len; i++) lt_text_drop(out.headers->items[i]);
            lt_free(out.headers, sizeof(lt_texts) + sizeof(lt_text *) * (size_t)out.headers->cap);
        }
        lt_bytes_drop(out.body);
        lt_text_drop(out.file);
        lt_fn_drop(out.writer);
    }
    lt_buf_free(&body);
    wasi_http_types_list_tuple2_field_name_field_value_free(&entries);
    wasi_http_types_fields_drop_own(hs);
    guest_string_free(&pq);
    wasi_http_types_method_free(&method);
    return e;
}

static lt_err lt_http_serve(int64_t port, lt_fn handler) {
    return lt_http_serve_on(NULL, port, 0, 0, 0, 0, handler);
}

// The component's export: the host calls it once per instance.
void exports_wasi_http_incoming_handler_handle(exports_wasi_http_incoming_handler_own_incoming_request_t request, exports_wasi_http_incoming_handler_own_response_outparam_t response_out) {
    lt_wasm_http.req = wasi_http_types_borrow_incoming_request(request);
    lt_wasm_http.out = response_out;
    lt_wasm_http.active = true;
    lt_err e = lt_program_main();
    if (e.obj) {
        lt_text *m = lt_error_message(e);
        lt_log("ERROR", m);
        lt_text_drop(m);
        lt_iface_drop(e);
        lt_wasm_respond_text(500, "internal server error");
    } else if (!lt_wasm_http.answered) {
        lt_wasm_log_error("main ended without calling http.serve, so the request has no answer");
        lt_wasm_respond_text(500, "internal server error");
    }
    fflush(stdout);
    wasi_http_types_incoming_request_drop_own(request);
}
